
/**
 * Parses a complete weekly meal plan and aggregates all required ingredients 
 * into a single unified grocery list, grouped by ingredient category.
 *
 * @param {Object} weeklyMealPlan - The structured 7-day meal plan generated by generateWeeklyMealPlan.
 * @param {Array} ingredients - The master library of available ingredients to look up metadata (name, unit, category).
 * @returns {Object} - An object where keys are categories (e.g., 'protein', 'vegetable') and values are arrays of ingredient requirement objects sorted alphabetically by name.
 */
export function formatIngredientDisplay(totalQuantity, unitStr) {
  const match = unitStr.match(/^([\d.]+)\s*(.*)$/);
  if (!match) return `${Math.round(totalQuantity * 10) / 10} ${unitStr}`;

  const baseUnitVal = parseFloat(match[1]); 
  const baseUnitStr = match[2]; 

  const calculatedTotal = totalQuantity * baseUnitVal;
  
  // Pluralization for countable units
  if (baseUnitStr === "large egg") {
    const rounded = Math.round(calculatedTotal);
    return `${rounded} large egg${rounded !== 1 ? 's' : ''}`;
  }

  // Round weight/volume to 1 decimal place
  const rounded = Math.round(calculatedTotal * 10) / 10;
  
  if (baseUnitStr.startsWith("g") || baseUnitStr.startsWith("ml")) {
    return `${rounded}${baseUnitStr}`;
  }
  
  return `${rounded} ${baseUnitStr}`;
}

export function generateGroceryList(weeklyMealPlan, ingredients) {
  const aggregatedMap = {};

  // 1. Accumulate all quantities by iterating through every day and every meal
  weeklyMealPlan.days.forEach(day => {
    Object.values(day.meals).forEach(meal => {
      // Handle potential null meals gracefully
      if (meal && meal.ingredients) {
        meal.ingredients.forEach(req => {
          // If we haven't seen this ingredient yet, initialize its tracker
          if (!aggregatedMap[req.ingredientId]) {
            const ingData = ingredients.find(i => i.id === req.ingredientId);
            if (ingData) {
              aggregatedMap[req.ingredientId] = {
                ingredientId: ingData.id,
                name: ingData.name,
                category: ingData.category,
                unit: ingData.unit,
                totalQuantity: 0
              };
            }
          }
          
          // Add the recipe's quantity to our running total
          if (aggregatedMap[req.ingredientId]) {
            aggregatedMap[req.ingredientId].totalQuantity += req.quantity;
          }
        });
      }
    });
  });

  // 2. Group items by their food category
  const groupedList = {};
  Object.values(aggregatedMap).forEach(item => {
    // Round quantity to 2 decimal places to avoid floating point math weirdness like 1.9999999
    item.totalQuantity = Math.round(item.totalQuantity * 100) / 100;
    item.displayQuantity = formatIngredientDisplay(item.totalQuantity, item.unit);
    
    if (!groupedList[item.category]) {
      groupedList[item.category] = [];
    }
    groupedList[item.category].push(item);
  });

  // 3. Sort each category array alphabetically by ingredient name
  Object.keys(groupedList).forEach(category => {
    groupedList[category].sort((a, b) => a.name.localeCompare(b.name));
  });

  return groupedList;
}

/**
 * Filters a grouped grocery list to remove ingredients the user already owns.
 * Kept strictly separate from generateGroceryList so the UI can later optionally 
 * toggle between a "Full Recipe Breakdown" and an "Actual Shopping List".
 *
 * @param {Object} groceryList - The grouped grocery list produced by generateGroceryList.
 * @param {Array<string>} availableIngredientIds - Array of ingredient IDs the user has in their pantry.
 * @returns {Object} - A new grocery list structured the same way, but excluding owned items. Categories that become empty are omitted entirely.
 */
export function excludeAvailableIngredients(groceryList, availableIngredientIds) {
  const filteredList = {};

  // Safety check
  if (!availableIngredientIds || availableIngredientIds.length === 0) {
    return groceryList;
  }

  Object.entries(groceryList).forEach(([category, items]) => {
    // Keep only items that are NOT in the user's available pantry
    const neededItems = items.filter(item => !availableIngredientIds.includes(item.ingredientId));
    
    // Only add the category to our new list if it still has items in it
    if (neededItems.length > 0) {
      filteredList[category] = neededItems;
    }
  });

  return filteredList;
}


